-- Reported questions and commands: immutable full teaching payload; retained normalized bank is unchanged.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='30s';
SELECT pg_advisory_xact_lock(hashtext('grammar-content-import'));
DO $guard$ BEGIN
 IF EXISTS(SELECT 1 FROM grammar.content_releases WHERE version='core-2026-09-v4' AND content_hash<>'87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d') THEN RAISE EXCEPTION 'Published release is immutable'; END IF;
 IF EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v4' AND slug='reported-questions' AND (catalog_hash<>'87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d' OR payload_md5<>'f23469b1072525c648080bb766ffd485')) THEN RAISE EXCEPTION 'Catalog payload conflict: use a new version'; END IF;
