DO $base$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reported-questions' AND catalog_hash='e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4' AND payload_md5='123d18130398bcd0c34d9a7e2fc9e189' AND md5((payload->'quizItems')::text)='aea0e73ef6682a81a7af68746ede3c68') THEN RAISE EXCEPTION 'Base archive or retained questions differ'; END IF;
END $base$;
INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','reported-questions','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"reported-questions","title":"Reported questions and commands","level":"B1","order":51,"summary":"Embed a question in a report without carrying direct-question word order into the embedded clause.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Yes/no questions use if or whether","Wh-questions keep the question word","Commands use an infinitive pattern","Adjust viewpoint carefully"],"rules":[{"title":"Yes/no questions use if or whether","explanation":"A reported yes/no question commonly starts with asked if or asked whether. The embedded clause has **statement order**, with subject before verb. A report of a question is not itself necessarily a question and usually ends with a full stop.","pattern":"She asked **whether I was ready**.","commonMistakes":["She asked was I ready keeps direct-question order where an embedded clause is needed."],"examples":["Report the question with statement order: “Did she prepare the visitor guide?” → He asked whether **she had prepared the visitor guide**.","Report the question with statement order: “Did she restore the old portrait?” → He asked whether **she had restored the old portrait**."],"skill":"form"},{"title":"Wh-questions keep the question word","explanation":"Who, what, where, when, why and how stay at the start of the embedded clause. Remove do-support when it only formed the direct question and put the lexical verb into the appropriate tense.","pattern":"“Where do you work?” → She asked **where I worked**.","commonMistakes":["Where did I work inside a statement report incorrectly retains inversion and do-support."],"examples":["Report with backshift: “When will they prepare the visitor guide?” → She asked when **they would prepare the visitor guide**.","Report with backshift: “When will they restore the old portrait?” → She asked when **they would restore the old portrait**."],"skill":"meaning"},{"title":"Commands use an infinitive pattern","explanation":"Tell or ask someone **to do** something can report an instruction or request. A negative command uses **not to do**. Keep the person receiving the instruction as the object of told or asked.","pattern":"She told us **to wait**. / She asked us **not to leave**.","commonMistakes":["Told us wait omits to in this reported-command pattern."],"examples":["Report the instruction: “Please prepare the visitor guide.” → She asked us **to prepare the visitor guide**.","Report the instruction: “Please restore the old portrait.” → She asked us **to restore the old portrait**."],"skill":"contrast"},{"title":"Adjust viewpoint carefully","explanation":"Pronouns, time words and backshift depend on the reporting context, just as in reported statements. Subject questions require special care: Who called? already has subject-first order and does not contain removable do-support.","pattern":"He asked **who had called**.","commonMistakes":["Whether is preferred or required in some structures, such as whether to leave and after prepositions; if cannot replace it everywhere."],"examples":["Report “Do not prepare the visitor guide yet.” → She told us **not to prepare the visitor guide yet**.","Report “Do not restore the old portrait yet.” → She told us **not to restore the old portrait yet**."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-questions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Embed a question in a report without carrying direct-question word order into the embedded clause.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Yes/no questions use if or whether","explanation":"A reported yes/no question commonly starts with asked if or asked whether. The embedded clause has **statement order**, with subject before verb. A report of a question is not itself necessarily a question and usually ends with a full stop.","pattern":"She asked **whether I was ready**.","commonMistakes":["She asked was I ready keeps direct-question order where an embedded clause is needed."],"examples":["Report the question with statement order: “Did she prepare the visitor guide?” → He asked whether **she had prepared the visitor guide**.","Report the question with statement order: “Did she restore the old portrait?” → He asked whether **she had restored the old portrait**."],"skill":"form","id":"reported-questions-foundation-1","domain":"content-clauses","referenceIds":["bc-reported-questions"],"readingVersion":"core-2026-09-v3"},{"title":"Wh-questions keep the question word","explanation":"Who, what, where, when, why and how stay at the start of the embedded clause. Remove do-support when it only formed the direct question and put the lexical verb into the appropriate tense.","pattern":"“Where do you work?” → She asked **where I worked**.","commonMistakes":["Where did I work inside a statement report incorrectly retains inversion and do-support."],"examples":["Report with backshift: “When will they prepare the visitor guide?” → She asked when **they would prepare the visitor guide**.","Report with backshift: “When will they restore the old portrait?” → She asked when **they would restore the old portrait**."],"skill":"meaning","id":"reported-questions-foundation-2","domain":"content-clauses","referenceIds":["bc-reported-questions"],"readingVersion":"core-2026-09-v3"},{"title":"Commands use an infinitive pattern","explanation":"Tell or ask someone **to do** something can report an instruction or request. A negative command uses **not to do**. Keep the person receiving the instruction as the object of told or asked.","pattern":"She told us **to wait**. / She asked us **not to leave**.","commonMistakes":["Told us wait omits to in this reported-command pattern."],"examples":["Report the instruction: “Please prepare the visitor guide.” → She asked us **to prepare the visitor guide**.","Report the instruction: “Please restore the old portrait.” → She asked us **to restore the old portrait**."],"skill":"contrast","id":"reported-questions-foundation-3","domain":"content-clauses","referenceIds":["bc-reported-questions"],"readingVersion":"core-2026-09-v3"},{"title":"Adjust viewpoint carefully","explanation":"Pronouns, time words and backshift depend on the reporting context, just as in reported statements. Subject questions require special care: Who called? already has subject-first order and does not contain removable do-support.","pattern":"He asked **who had called**.","commonMistakes":["Whether is preferred or required in some structures, such as whether to leave and after prepositions; if cannot replace it everywhere."],"examples":["Report “Do not prepare the visitor guide yet.” → She told us **not to prepare the visitor guide yet**.","Report “Do not restore the old portrait yet.” → She told us **not to restore the old portrait yet**."],"skill":"application","id":"reported-questions-foundation-4","domain":"content-clauses","referenceIds":["bc-reported-questions"],"readingVersion":"core-2026-09-v3"}],"recap":["She asked **whether I was ready**.","“Where do you work?” → She asked **where I worked**.","She told us **to wait**. / She asked us **not to leave**.","He asked **who had called**."],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["reported-statements"],"readingReferenceIds":["bc-reported-questions"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reported-questions'
ON CONFLICT(version,slug) DO NOTHING;
DO $verify$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v4' AND slug='reported-questions' AND payload_md5='f23469b1072525c648080bb766ffd485') THEN RAISE EXCEPTION 'Full payload mismatch'; END IF;
 IF (SELECT count(*) FROM grammar.grammar_quiz_items WHERE topic_slug='reported-questions')<>200 THEN RAISE EXCEPTION 'Question count mismatch'; END IF;
